def valid_kurung(s):
    pasangan = {')': '(', ']': '[', '}': '{'}
    tumpukan = []
    for ch in s:
        if ch in '([{':
            tumpukan.append(ch)
        else:
            if not tumpukan or tumpukan[-1] != pasangan[ch]:
                return False
            tumpukan.pop()
    return not tumpukan
